// DashboardCostStats is the resolver for the dashboardCostStats field.
func (r *queryResolver) DashboardCostStats(ctx context.Context) (*biz.DashboardCostStats, error) {
	if err := authz.RequireScope(ctx, scopes.ScopeReadDashboard); err != nil {
		return nil, err
	}
	location := r.systemService.TimeLocation(authz.WithScopeDecision(ctx, scopes.ScopeReadDashboard))
	settings, err := r.systemService.GeneralSettings(authz.WithScopeDecision(ctx, scopes.ScopeReadDashboard))
	if err != nil {
		return nil, err
	}
	result, err := biz.QueryDashboardCosts(ctx, r.client, xtime.GetCalendarPeriods(location), location.String())
	if err != nil {
		return nil, err
	}
	result.CurrencyCode = settings.CurrencyCode
	return result, nil
}
